--[[
  NIGHTDLC · packed · night_pc_fixed
  XOR + Base64 wrapper (same format as the example)
]]

local function _ndlc_decode(payload, key)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    payload = payload:gsub("[^" .. alphabet .. "=]", "")
    local data = {}
    local build = {}

    local function push(n)
        build[#build + 1] = string.char(n)
        if #build >= 4096 then
            data[#data + 1] = table.concat(build)
            build = {}
        end
    end

    for i = 1, #payload, 4 do
        local a = alphabet:find(payload:sub(i, i), 1, true) or 1
        local b = alphabet:find(payload:sub(i + 1, i + 1), 1, true) or 1
        local c = alphabet:find(payload:sub(i + 2, i + 2), 1, true) or 1
        local d = alphabet:find(payload:sub(i + 3, i + 3), 1, true) or 1
        a, b, c, d = a - 1, b - 1, c - 1, d - 1
        local n = a * 262144 + b * 4096 + c * 64 + d
        push(math.floor(n / 65536) % 256)
        if payload:sub(i + 2, i + 2) ~= "=" then
            push(math.floor(n / 256) % 256)
        end
        if payload:sub(i + 3, i + 3) ~= "=" then
            push(n % 256)
        end
    end

    if #build > 0 then data[#data + 1] = table.concat(build) end
    local raw = table.concat(data)
    local out, chunk = {}, {}
    local klen = #key

    for i = 1, #raw do
        local byte = string.byte(raw, i)
        local kb = key[((i - 1) % klen) + 1]
        local x, y, r, p = byte, kb, 0, 1
        while x > 0 or y > 0 do
            local xb, yb = x % 2, y % 2
            if xb ~= yb then r = r + p end
            x, y, p = (x - xb) / 2, (y - yb) / 2, p * 2
        end
        chunk[#chunk + 1] = string.char(r)
        if #chunk >= 4096 then
            out[#out + 1] = table.concat(chunk)
            chunk = {}
        end
    end

    if #chunk > 0 then out[#out + 1] = table.concat(chunk) end
    return table.concat(out)
end

local _KEY = {255,7,200,66,248,93,173,17,59,178,91,124,198,105,219,221,113,25,50,142,213,241,19,117,18,73,82,218,248,143,155,150}
local _PAYLOAD = [==[

]==]

local source = _ndlc_decode(_PAYLOAD, _KEY)
local chunk, err = loadstring(source)
if not chunk then
    error("NIGHTDLC: failed to load decoded script: " .. tostring(err))
end
return chunk()
